CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS guilds (id text PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guild_settings (guild_id text PRIMARY KEY REFERENCES guilds(id) ON DELETE CASCADE, quarantine_role_id text, verified_role_id text, mod_channel_id text, enabled boolean NOT NULL DEFAULT true, config jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), discord_id text NOT NULL UNIQUE, username text, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz);
CREATE TABLE IF NOT EXISTS devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, device_key text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fingerprints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id uuid REFERENCES devices(id) ON DELETE CASCADE, fingerprint text NOT NULL, kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, user_id uuid REFERENCES users(id), status text NOT NULL DEFAULT 'pending', challenge text, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, user_id uuid REFERENCES users(id), score integer NOT NULL, outcome text NOT NULL, severity text NOT NULL, signals jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_reasons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), risk_score_id uuid REFERENCES risk_scores(id) ON DELETE CASCADE, code text NOT NULL, category text NOT NULL, points integer NOT NULL, detail text NOT NULL);
CREATE TABLE IF NOT EXISTS cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, user_id uuid REFERENCES users(id), status text NOT NULL DEFAULT 'open', outcome text NOT NULL, risk_score_id uuid REFERENCES risk_scores(id), assigned_to text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS case_timeline_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid REFERENCES cases(id) ON DELETE CASCADE, actor_id text, event_type text NOT NULL, detail text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS case_links (case_id uuid REFERENCES cases(id) ON DELETE CASCADE, related_case_id uuid REFERENCES cases(id) ON DELETE CASCADE, relation text NOT NULL, PRIMARY KEY (case_id, related_case_id));
CREATE TABLE IF NOT EXISTS trusted_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, user_id uuid REFERENCES users(id), device_id uuid REFERENCES devices(id), trust_score integer NOT NULL DEFAULT 100, last_confirmed_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz);
CREATE TABLE IF NOT EXISTS watchlists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, selector text NOT NULL, selector_type text NOT NULL, reason text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text, actor_id text, action text NOT NULL, target text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS risk_scores_user_idx ON risk_scores(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS cases_guild_status_idx ON cases(guild_id, status);
